import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    inside = {}
    entry, exits = set(), set()
    for i in range(n):
        name, act = data[1 + 2 * i], data[2 + 2 * i]
        cur = inside.get(name, False)
        if act == 'enter':
            if cur:
                entry.add(name)
            inside[name] = True
        else:
            if not cur:
                exits.add(name)
            inside[name] = False
    for name, v in inside.items():
        if v:
            entry.add(name)
    print(' '.join(sorted(entry)) or 'NONE')
    print(' '.join(sorted(exits)) or 'NONE')

main()

